import fs from "node:fs";
import path from "node:path";
import { getDb } from "./db";
import { getSecret } from "./secrets";

/**
 * On-disk archive of what SEC gave us.
 *
 * Two different things are stored. The `companyfacts` JSON is the raw material
 * every normalized metric is derived from, so keeping it means the whole
 * financial history can be recomputed without touching the network again. The
 * filing documents themselves (10-K, 10-Q) are what a human actually reads;
 * those are fetched on demand and cached, because pulling every document for
 * every company would be tens of thousands of requests.
 */

export function archiveRoot(): string {
  const configured = process.env.SEC_ARCHIVE_PATH || "data/sec";
  return path.isAbsolute(configured)
    ? configured
    : path.join(/* turbopackIgnore: true */ process.cwd(), configured);
}

function tickerDir(ticker: string): string {
  // Ticker comes from a validated route param, but keep the path defensive.
  const safe = ticker.replace(/[^A-Za-z0-9.\-]/g, "_").toUpperCase();
  return path.join(archiveRoot(), safe);
}

/* ------------------------------------------------------------------ */
/* companyfacts snapshot                                               */
/* ------------------------------------------------------------------ */

export function saveCompanyFacts(
  ticker: string,
  data: unknown,
): { path: string; bytes: number } {
  const dir = tickerDir(ticker);
  fs.mkdirSync(dir, { recursive: true });
  const file = path.join(dir, "companyfacts.json");
  const payload = JSON.stringify(data);
  fs.writeFileSync(file, payload);
  return { path: file, bytes: Buffer.byteLength(payload) };
}

export function companyFactsInfo(ticker: string): { path: string; bytes: number } | null {
  const file = path.join(tickerDir(ticker), "companyfacts.json");
  try {
    return { path: file, bytes: fs.statSync(file).size };
  } catch {
    return null;
  }
}

/* ------------------------------------------------------------------ */
/* filing documents                                                    */
/* ------------------------------------------------------------------ */

export type FilingRef = {
  accn: string;
  form: string;
  periodEnd: string | null;
  filed: string | null;
  primaryDocument: string | null;
  docUrl: string | null;
  storedPath: string | null;
  storedBytes: number | null;
};

/** EDGAR archive URL for a filing's primary document. */
export function buildDocUrl(cik: string, accn: string, primaryDocument: string): string {
  const cikPlain = String(Number(cik)); // archive paths drop leading zeros
  const accnPlain = accn.replace(/-/g, "");
  return `https://www.sec.gov/Archives/edgar/data/${cikPlain}/${accnPlain}/${primaryDocument}`;
}

/** Landing page for the whole filing, useful when the document is missing. */
export function buildIndexUrl(cik: string, accn: string): string {
  return `https://www.sec.gov/Archives/edgar/data/${String(Number(cik))}/${accn.replace(/-/g, "")}/`;
}

export function recordFilingDocs(
  ticker: string,
  docs: { accn: string; form: string; filed: string; periodEnd: string; primaryDocument: string; docUrl: string }[],
): number {
  const db = getDb();
  const stmt = db.prepare(`
    INSERT INTO filings (ticker, accn, form, period_end, filed, primary_document, doc_url)
    VALUES (?,?,?,?,?,?,?)
    ON CONFLICT(ticker, accn) DO UPDATE SET
      form = COALESCE(excluded.form, filings.form),
      period_end = COALESCE(excluded.period_end, filings.period_end),
      filed = COALESCE(excluded.filed, filings.filed),
      primary_document = excluded.primary_document,
      doc_url = excluded.doc_url
  `);
  db.transaction(() => {
    for (const d of docs) {
      stmt.run(ticker, d.accn, d.form, d.periodEnd || null, d.filed || null, d.primaryDocument, d.docUrl);
    }
  })();
  return docs.length;
}

export function getFiling(ticker: string, accn: string): FilingRef | null {
  const row = getDb()
    .prepare(
      `SELECT accn, form, period_end AS periodEnd, filed,
              primary_document AS primaryDocument, doc_url AS docUrl,
              stored_path AS storedPath, stored_bytes AS storedBytes
       FROM filings WHERE ticker = ? AND accn = ?`,
    )
    .get(ticker, accn) as FilingRef | undefined;
  return row ?? null;
}

export function listFilings(ticker?: string, limit = 400): (FilingRef & { ticker: string })[] {
  // Only report forms, and only those with a document — anything else cannot be
  // opened, so listing it would just be noise. `companyfacts` also seeds this
  // table with 8-K and proxy accession numbers that carry no primary document.
  const forms = `form IN ('10-K','10-Q','20-F','40-F','10-K/A','10-Q/A') AND primary_document IS NOT NULL`;
  const where = ticker ? `WHERE ticker = ? AND ${forms}` : `WHERE ${forms}`;
  const params = ticker ? [ticker, limit] : [limit];
  return getDb()
    .prepare(
      `SELECT ticker, accn, form, period_end AS periodEnd, filed,
              primary_document AS primaryDocument, doc_url AS docUrl,
              stored_path AS storedPath, stored_bytes AS storedBytes
       FROM filings ${where}
       ORDER BY filed DESC, ticker
       LIMIT ?`,
    )
    .all(...params) as (FilingRef & { ticker: string })[];
}

/**
 * Return the filing document from disk, downloading it once if needed.
 * Cached under data/sec/<TICKER>/<accn>-<document>.
 */
export async function ensureFilingOnDisk(
  ticker: string,
  accn: string,
): Promise<{ file: string; bytes: number; contentType: string; filename: string }> {
  const filing = getFiling(ticker, accn);
  if (!filing) throw new Error(`Výkaz ${accn} pro ${ticker} není v databázi`);
  if (!filing.docUrl || !filing.primaryDocument) {
    throw new Error(
      `U výkazu ${accn} neznáme primární dokument — stáhni ticker znovu, metadata se doplní ze SEC submissions`,
    );
  }

  const dir = tickerDir(ticker);
  fs.mkdirSync(dir, { recursive: true });
  const filename = `${accn}-${path.basename(filing.primaryDocument)}`;
  const file = path.join(dir, filename);

  const contentType = filename.toLowerCase().endsWith(".pdf")
    ? "application/pdf"
    : filename.toLowerCase().endsWith(".txt")
      ? "text/plain; charset=utf-8"
      : "text/html; charset=utf-8";

  if (fs.existsSync(file) && fs.statSync(file).size > 0) {
    return { file, bytes: fs.statSync(file).size, contentType, filename };
  }

  const ua = getSecret("SEC_USER_AGENT");
  if (!ua) throw new Error("SEC_USER_AGENT není nastavený");

  const res = await fetch(filing.docUrl, {
    headers: { "User-Agent": ua, Accept: "*/*" },
    cache: "no-store",
    signal: AbortSignal.timeout(120_000),
  });
  if (!res.ok) throw new Error(`SEC vrátil ${res.status} pro ${filing.docUrl}`);

  const buffer = Buffer.from(await res.arrayBuffer());
  fs.writeFileSync(file, buffer);

  getDb()
    .prepare(
      `UPDATE filings SET stored_path = ?, stored_bytes = ?, stored_at = ?
       WHERE ticker = ? AND accn = ?`,
    )
    .run(file, buffer.length, new Date().toISOString(), ticker, accn);

  return { file, bytes: buffer.length, contentType, filename };
}

export function archiveUsage(): { files: number; bytes: number } {
  let files = 0;
  let bytes = 0;
  const walk = (dir: string) => {
    let entries: fs.Dirent[];
    try {
      entries = fs.readdirSync(dir, { withFileTypes: true });
    } catch {
      return;
    }
    for (const e of entries) {
      const full = path.join(dir, e.name);
      if (e.isDirectory()) walk(full);
      else {
        files++;
        try {
          bytes += fs.statSync(full).size;
        } catch {
          /* file vanished between readdir and stat */
        }
      }
    }
  };
  walk(archiveRoot());
  return { files, bytes };
}
