import { getDb } from "./db";
import { getSplits, splitFactorLookup } from "./prices";
import {
  BENCHMARK,
  betaWindowStart,
  epsGrowth,
  growthBase,
  latestBeta,
  loadBenchmark,
  peg,
} from "./valuation-extra";

/**
 * Current-state metrics for one company, computed with targeted queries.
 *
 * The full derived engine builds decades of series; comparing a handful of
 * companies only needs their latest numbers, so this reads just the rows that
 * feed them. That keeps a nine-company comparison in the tens of milliseconds
 * instead of loading nine complete price histories.
 */

export type Snapshot = {
  ticker: string;
  name: string | null;
  sector: string | null;
  subIndustry: string | null;
  price: number | null;
  priceDate: string | null;
  marketCap: number | null;
  pe: number | null;
  ps: number | null;
  pb: number | null;
  evToEbit: number | null;
  /** Trailing P/E over annualised 3-year EPS growth. */
  peg: number | null;
  /** Annualised EPS growth behind the PEG, in percent. */
  epsGrowth3y: number | null;
  /** Against SPY, from five years of returns. */
  beta: number | null;
  ttmRevenue: number | null;
  ttmNetIncome: number | null;
  grossMargin: number | null;
  netMargin: number | null;
  operatingMargin: number | null;
  roe: number | null;
  debtToEquity: number | null;
  dividendYield: number | null;
  revenueGrowth: number | null;
  hasPrices: boolean;
  /** Set when the snapshot was deliberately computed as of a past date. */
  asOf?: string | null;
};

type Row = { period_end: string; value: number };

/**
 * Point-in-time gate for a `financials` query.
 *
 * A figure counts as knowable on a date only once a filing disclosed it, and
 * that is `first_filed` — not `period_end`, which is weeks earlier, and not
 * `filed`, which can be years later after a restatement. Without this an
 * as-of-2014 snapshot would quietly use the 2013 annual report a month before
 * anyone could read it.
 */
const knownBy = (asOf?: string | null) =>
  asOf ? " AND COALESCE(first_filed, filed, period_end) <= ?" : "";

/** Same gate for dated rows that need no filing (prices, dividends). */
const dateBy = (column: string, asOf?: string | null) =>
  asOf ? ` AND ${column} <= ?` : "";

/** Bound value for the gates above — empty when no cut-off is in force. */
const gate = (asOf?: string | null): string[] => (asOf ? [asOf] : []);

function latestPit(ticker: string, metric: string, asOf?: string | null): Row | null {
  return (
    (getDb()
      .prepare(
        `SELECT period_end, value FROM financials
         WHERE ticker = ? AND metric = ? AND period_type = 'PIT'${knownBy(asOf)}
         ORDER BY period_end DESC LIMIT 1`,
      )
      .get(ticker, metric, ...gate(asOf)) as Row | undefined) ?? null
  );
}

/** Sum of the last four reported quarters, or null if fewer than four exist. */
function ttm(ticker: string, metric: string, asOf?: string | null): number | null {
  const rows = getDb()
    .prepare(
      `SELECT period_end, value FROM financials
       WHERE ticker = ? AND metric = ? AND period_type = 'Q'${knownBy(asOf)}
       ORDER BY period_end DESC LIMIT 4`,
    )
    .all(ticker, metric, ...gate(asOf)) as Row[];
  if (rows.length < 4) return null;
  // Reject a window with a gap — four rows spanning six years is not a year.
  const span =
    (Date.parse(rows[0].period_end) - Date.parse(rows[3].period_end)) / 86_400_000;
  if (span < 240 || span > 400) return null;
  return rows.reduce((s, r) => s + r.value, 0);
}

const ratio = (a: number | null, b: number | null): number | null =>
  a !== null && b !== null && b !== 0 ? a / b : null;

const pct = (a: number | null, b: number | null): number | null =>
  a !== null && b !== null && b !== 0 ? (a / b) * 100 : null;

/**
 * Everything the app knows about one company as one row of numbers.
 *
 * `asOf` recomputes it as of a past date: prices up to that day, and figures
 * only from filings that were already public then. That is what makes a
 * backtest of any judgement built on this snapshot honest — without it the
 * 2013 annual report would be "known" the day the fiscal year ended.
 */
export function computeSnapshot(ticker: string, asOf?: string | null): Snapshot | null {
  const db = getDb();

  const company = db
    .prepare(
      `SELECT ticker, name, sector, sub_industry AS subIndustry
       FROM companies WHERE ticker = ?`,
    )
    .get(ticker) as
    | { ticker: string; name: string | null; sector: string | null; subIndustry: string | null }
    | undefined;
  if (!company) return null;

  const last = db
    .prepare(
      `SELECT date, close FROM prices WHERE ticker = ? AND close IS NOT NULL${dateBy("date", asOf)}
       ORDER BY date DESC LIMIT 1`,
    )
    .get(ticker, ...gate(asOf)) as { date: string; close: number } | undefined;

  const sharesRow = latestPit(ticker, "shares_outstanding", asOf);
  let marketCap: number | null = null;
  if (last && sharesRow) {
    // Carry the reported count through any split since it was measured, so it
    // sits on the same basis as the price it multiplies.
    const factor = splitFactorLookup(getSplits(ticker));
    const shares = sharesRow.value * (factor(sharesRow.period_end) / factor(last.date));
    marketCap = last.close * shares;
  }

  const ttmRevenue = ttm(ticker, "revenue", asOf);
  const ttmNetIncome = ttm(ticker, "net_income", asOf);
  const ttmGross = ttm(ticker, "gross_profit", asOf);
  const ttmOperating = ttm(ticker, "operating_income", asOf);

  const equity = latestPit(ticker, "equity", asOf)?.value ?? null;
  const debtShort = latestPit(ticker, "debt_short", asOf)?.value ?? 0;
  const debtLong = latestPit(ticker, "debt_long", asOf)?.value ?? 0;
  const totalDebt = debtShort + debtLong;
  const cash = latestPit(ticker, "cash", asOf)?.value ?? 0;

  // Annual revenue growth from the two most recent fiscal years.
  const annual = db
    .prepare(
      `SELECT period_end, value FROM financials
       WHERE ticker = ? AND metric = 'revenue' AND period_type = 'FY'${knownBy(asOf)}
       ORDER BY period_end DESC LIMIT 2`,
    )
    .all(ticker, ...gate(asOf)) as Row[];
  const revenueGrowth =
    annual.length === 2 && annual[1].value !== 0
      ? ((annual[0].value - annual[1].value) / Math.abs(annual[1].value)) * 100
      : null;

  // Trailing dividends: the last four payments, matching the payer's cadence.
  const divs = db
    .prepare(
      `SELECT date, amount FROM dividends WHERE ticker = ?${dateBy("date", asOf)}
       ORDER BY date DESC LIMIT 4`,
    )
    .all(ticker, ...gate(asOf)) as { date: string; amount: number }[];
  const ttmDividend = divs.length
    ? divs.reduce((s, d) => s + d.amount, 0)
    : null;

  /*
   * EPS in today's shares at two points in time, for the PEG growth rate.
   * Computed from profit and share count rather than read from filings, which
   * keep old EPS on the pre-split basis (same reasoning as in metrics.ts).
   */
  const factor = splitFactorLookup(getSplits(ticker));
  const epsAt = (date?: string | null): number | null => {
    const ni = ttm(ticker, "net_income", date);
    const sh = latestPit(ticker, "shares_outstanding", date);
    if (ni === null || !sh || sh.value <= 0) return null;
    return ni / (sh.value * factor(sh.period_end));
  };
  // Three years back from the day the current TTM became public — not from
  // today, or the base would slide a quarter away from the one the chart uses.
  const ttmKnown = (
    db
      .prepare(
        `SELECT MAX(k) AS k FROM (
           SELECT COALESCE(first_filed, filed, period_end) AS k FROM financials
           WHERE ticker = ? AND metric = 'net_income' AND period_type = 'Q'${knownBy(asOf)}
           ORDER BY period_end DESC LIMIT 4)`,
      )
      .get(ticker, ...gate(asOf)) as { k: string | null }
  ).k;
  const epsGrowth3y = ttmKnown
    ? epsGrowth(epsAt(asOf), epsAt(growthBase(ttmKnown)))
    : null;

  let beta: number | null = null;
  if (last && ticker !== BENCHMARK) {
    const bars = db
      .prepare(
        `SELECT date, close, adj_close AS adj FROM prices
         WHERE ticker = ? AND close IS NOT NULL AND date >= ?${dateBy("date", asOf)}
         ORDER BY date`,
      )
      .all(ticker, betaWindowStart(last.date), ...gate(asOf)) as {
      date: string;
      close: number;
      adj: number | null;
    }[];
    beta = latestBeta(
      bars.map((b) => ({ date: b.date, value: b.adj ?? b.close / factor(b.date) })),
      loadBenchmark(asOf).filter((p) => p.date >= betaWindowStart(last.date)),
    );
  }

  const enterpriseValue =
    marketCap !== null ? marketCap + totalDebt - cash : null;

  return {
    ticker: company.ticker,
    name: company.name,
    sector: company.sector,
    subIndustry: company.subIndustry,
    price: last?.close ?? null,
    priceDate: last?.date ?? null,
    marketCap,
    // A loss makes these meaningless rather than merely large, so they stay null.
    pe: ttmNetIncome !== null && ttmNetIncome > 0 ? ratio(marketCap, ttmNetIncome) : null,
    ps: ttmRevenue !== null && ttmRevenue > 0 ? ratio(marketCap, ttmRevenue) : null,
    pb: equity !== null && equity > 0 ? ratio(marketCap, equity) : null,
    evToEbit:
      ttmOperating !== null && ttmOperating > 0 ? ratio(enterpriseValue, ttmOperating) : null,
    peg: peg(
      ttmNetIncome !== null && ttmNetIncome > 0 ? ratio(marketCap, ttmNetIncome) : null,
      epsGrowth3y,
    ),
    epsGrowth3y,
    beta,
    ttmRevenue,
    ttmNetIncome,
    grossMargin: pct(ttmGross, ttmRevenue),
    netMargin: pct(ttmNetIncome, ttmRevenue),
    operatingMargin: pct(ttmOperating, ttmRevenue),
    roe: equity !== null && equity > 0 ? pct(ttmNetIncome, equity) : null,
    debtToEquity: equity !== null && equity > 0 ? ratio(totalDebt, equity) : null,
    dividendYield: last?.close ? pct(ttmDividend, last.close) : null,
    revenueGrowth,
    hasPrices: Boolean(last),
    asOf: asOf ?? null,
  };
}

/* ------------------------------------------------------------------ */
/* peer selection                                                      */
/* ------------------------------------------------------------------ */

/** Rough market cap for many tickers at once, for ranking candidates. */
function roughMarketCaps(tickers: string[]): Map<string, number> {
  const out = new Map<string, number>();
  if (tickers.length === 0) return out;

  const placeholders = tickers.map(() => "?").join(",");
  const rows = getDb()
    .prepare(
      `SELECT c.ticker,
              (SELECT close FROM prices p WHERE p.ticker = c.ticker AND close IS NOT NULL
                ORDER BY date DESC LIMIT 1) AS price,
              (SELECT value FROM financials f WHERE f.ticker = c.ticker
                 AND f.metric = 'shares_outstanding' AND f.period_type = 'PIT'
                ORDER BY period_end DESC LIMIT 1) AS shares
       FROM companies c WHERE c.ticker IN (${placeholders})`,
    )
    .all(...tickers) as { ticker: string; price: number | null; shares: number | null }[];

  for (const r of rows) {
    if (r.price && r.shares) out.set(r.ticker, r.price * r.shares);
  }
  return out;
}

/**
 * Companies closest in size within the same corner of the market.
 *
 * Sub-industry first, because that is the group whose multiples are actually
 * comparable; if it is too thin, widen to the sector rather than return
 * nothing. Ranking by market-cap distance keeps a mega-cap from being compared
 * against a minor player that happens to share a label.
 */
export function findPeers(ticker: string, count = 4): string[] {
  const db = getDb();
  const me = db
    .prepare(`SELECT sector, sub_industry AS subIndustry FROM companies WHERE ticker = ?`)
    .get(ticker) as { sector: string | null; subIndustry: string | null } | undefined;
  if (!me) return [];

  /*
   * Candidates come from `companies`, not from the index list: a company
   * nobody's index knows still has a classification of its own, and it should
   * both find peers and be findable as one.
   */
  const pick = (where: string, param: string) =>
    (
      db
        .prepare(`SELECT ticker FROM companies WHERE ${where} AND ticker <> ?`)
        .all(param, ticker) as { ticker: string }[]
    ).map((r) => r.ticker);

  let candidates = me.subIndustry ? pick("sub_industry = ?", me.subIndustry) : [];
  if (candidates.length < count && me.sector) {
    const bySector = pick("sector = ?", me.sector);
    candidates = [...new Set([...candidates, ...bySector])];
  }
  if (candidates.length === 0) return [];

  const caps = roughMarketCaps([ticker, ...candidates]);
  const mine = caps.get(ticker);
  if (!mine) return candidates.slice(0, count);

  return candidates
    .filter((t) => caps.has(t))
    // Distance in log space: "half my size" and "twice my size" are equally far.
    .sort(
      (a, b) =>
        Math.abs(Math.log(caps.get(a)! / mine)) - Math.abs(Math.log(caps.get(b)! / mine)),
    )
    .slice(0, count);
}
