import { getDb } from "./db";
import { getSplits, splitFactorLookup } from "./prices";
import type { SeriesPoint } from "./types";

/**
 * Beta against the market and the PEG ratio.
 *
 * Both are shared by the full derived engine (a series for the chart) and by
 * the snapshot (one number for the summary and the peer table), so the two can
 * never disagree about what the figure means.
 */

/** The market that beta is measured against. */
export const BENCHMARK = "SPY";

/** Beta looks back this far — the usual "5Y" in quote screens. */
export const BETA_YEARS = 5;

/** A shorter history than this gives no beta at all rather than a noisy one. */
const BETA_MIN_YEARS = 2;

/** PEG divides P/E by EPS growth annualised over this many years. */
export const PEG_GROWTH_YEARS = 3;

const DAY = 86_400_000;
const yearsBefore = (date: string, years: number) =>
  new Date(Date.parse(date) - years * 365.25 * DAY).toISOString().slice(0, 10);

/* ------------------------------------------------------------------ */
/* beta                                                                */
/* ------------------------------------------------------------------ */

/**
 * The benchmark's total-return closes (dividends and splits folded in),
 * optionally cut off at `asOf`. Empty when SPY has not been downloaded.
 */
export function loadBenchmark(asOf?: string | null): SeriesPoint[] {
  const rows = getDb()
    .prepare(
      `SELECT date, close, adj_close AS adj FROM prices
       WHERE ticker = ? AND close IS NOT NULL${asOf ? " AND date <= ?" : ""}
       ORDER BY date`,
    )
    .all(BENCHMARK, ...(asOf ? [asOf] : [])) as { date: string; close: number; adj: number | null }[];
  const factor = splitFactorLookup(getSplits(BENCHMARK));
  return rows.map((r) => ({ date: r.date, value: r.adj ?? r.close / factor(r.date) }));
}

/** Last value on or before `date` in a date-sorted series. */
function asOfLookup(series: SeriesPoint[]): (date: string) => number | null {
  return (date: string) => {
    let lo = 0;
    let hi = series.length - 1;
    let hit = -1;
    while (lo <= hi) {
      const mid = (lo + hi) >> 1;
      if (series[mid].date <= date) {
        hit = mid;
        lo = mid + 1;
      } else hi = mid - 1;
    }
    return hit === -1 ? null : series[hit].value;
  };
}

/**
 * Paired period returns of the stock and the market.
 *
 * The two series need not share a bar size — a daily stock against weekly SPY
 * is normal here. Returns are therefore taken on the dates of whichever series
 * is coarser, with the other sampled as of those dates. Sampling the other way
 * round would pair five flat days of one side with one real move of the other.
 */
function pairedReturns(
  stock: SeriesPoint[],
  market: SeriesPoint[],
): { date: string; x: number; y: number }[] {
  const s = stock.filter((p) => p.value !== null && p.value > 0);
  const m = market.filter((p) => p.value !== null && p.value > 0);
  if (s.length < 3 || m.length < 3) return [];

  const from = s[0].date > m[0].date ? s[0].date : m[0].date;
  const to = s[s.length - 1].date < m[m.length - 1].date ? s[s.length - 1].date : m[m.length - 1].date;
  const inRange = (p: SeriesPoint) => p.date >= from && p.date <= to;
  const sIn = s.filter(inRange);
  const mIn = m.filter(inRange);
  const grid = (sIn.length <= mIn.length ? sIn : mIn).map((p) => p.date);
  const sAt = asOfLookup(s);
  const mAt = asOfLookup(m);

  const out: { date: string; x: number; y: number }[] = [];
  for (let i = 1; i < grid.length; i++) {
    const s0 = sAt(grid[i - 1]);
    const s1 = sAt(grid[i]);
    const m0 = mAt(grid[i - 1]);
    const m1 = mAt(grid[i]);
    if (!s0 || !s1 || !m0 || !m1) continue;
    out.push({ date: grid[i], x: m1 / m0 - 1, y: s1 / s0 - 1 });
  }
  return out;
}

/**
 * Rolling beta: covariance with the market over the market's variance, on the
 * trailing BETA_YEARS of returns ending at each date.
 */
export function betaSeries(stock: SeriesPoint[], market: SeriesPoint[]): SeriesPoint[] {
  const r = pairedReturns(stock, market);
  const out: SeriesPoint[] = [];
  let start = 0;
  let n = 0;
  let sx = 0;
  let sy = 0;
  let sxy = 0;
  let sxx = 0;

  for (let i = 0; i < r.length; i++) {
    n++;
    sx += r[i].x;
    sy += r[i].y;
    sxy += r[i].x * r[i].y;
    sxx += r[i].x * r[i].x;

    const windowStart = yearsBefore(r[i].date, BETA_YEARS);
    while (start < i && r[start].date <= windowStart) {
      n--;
      sx -= r[start].x;
      sy -= r[start].y;
      sxy -= r[start].x * r[start].y;
      sxx -= r[start].x * r[start].x;
      start++;
    }

    const enough = r[start].date <= yearsBefore(r[i].date, BETA_MIN_YEARS) && n >= 24;
    const varX = sxx / n - (sx / n) ** 2;
    out.push({
      date: r[i].date,
      value: enough && varX > 0 ? (sxy / n - (sx / n) * (sy / n)) / varX : null,
    });
  }
  return out;
}

/** Latest beta only — what the summary strip and the peer table show. */
export function latestBeta(stock: SeriesPoint[], market: SeriesPoint[]): number | null {
  // Only the last window matters; trimming first keeps a 30-year daily history cheap.
  const last = stock[stock.length - 1];
  if (!last) return null;
  const cut = yearsBefore(last.date, BETA_YEARS + 0.1);
  const series = betaSeries(
    stock.filter((p) => p.date >= cut),
    market.filter((p) => p.date >= cut),
  );
  for (let i = series.length - 1; i >= 0; i--) if (series[i].value !== null) return series[i].value;
  return null;
}

/* ------------------------------------------------------------------ */
/* PEG                                                                 */
/* ------------------------------------------------------------------ */

/**
 * Annualised growth of EPS between two values, in percent. Null unless both
 * ends are profits — growth out of a loss has no rate.
 */
export function epsGrowth(now: number | null, then: number | null): number | null {
  if (now === null || then === null || now <= 0 || then <= 0) return null;
  return ((now / then) ** (1 / PEG_GROWTH_YEARS) - 1) * 100;
}

/**
 * P/E over growth. Null for a loss (no P/E) and for shrinking or flat
 * earnings — a negative PEG reads as "cheap" and is the opposite.
 */
export function peg(pe: number | null, growthPct: number | null): number | null {
  if (pe === null || pe <= 0 || growthPct === null || growthPct <= 0) return null;
  return pe / growthPct;
}

/** The date PEG_GROWTH_YEARS before `date`, for looking up the old EPS. */
export const growthBase = (date: string) => yearsBefore(date, PEG_GROWTH_YEARS);

/** How far back a query needs prices for `latestBeta` to see a full window. */
export function betaWindowStart(date: string): string {
  return yearsBefore(date, BETA_YEARS + 0.1);
}
